#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Go-live wizard for River Monitor's public MVP (issue #7).
#
#   bash scripts/go_live_wizard.sh          # from the River checkout, on main
#   bash scripts/go_live_wizard.sh --help
#
# Overrides (env): RIVER_DIR, RIVER_PROJECT, TUNNEL_DIR, TUNNEL_REPO_NAME.
# Secrets go only to the tunnel's gitignored .env (TUNNEL_TOKEN) and River's
# Settings table (telegram_bot_token, written over stdin via docker exec).

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
RIVER_DIR="${RIVER_DIR:-$(git -C "$SCRIPT_DIR" rev-parse --show-toplevel 2>/dev/null || dirname "$SCRIPT_DIR")}"
RIVER_PROJECT="${RIVER_PROJECT:-my_river_level}"
TUNNEL_DIR="${TUNNEL_DIR:-$RIVER_DIR/../One-Time-Tools/cloudflare-tunnel}"
TUNNEL_PROJECT="cloudflare-tunnel"
TUNNEL_REPO_NAME="${TUNNEL_REPO_NAME:-cloudflare-tunnel}"
PUBLIC_URL="https://river.ohr3023.org"
PLACEHOLDER_TOKEN="placeholder-token"
PATH_REGEX='^/(pin(/.*)?|view/.+|edit/.+|pages/new|static/.+|healthz)$'
CF_DASHBOARD="https://one.dash.cloudflare.com/"
BOT_USERNAME=""
SMOKE_RESULT="not run"

die() { warn "$1"; printf '\n'; exit 1; }

usage() {
  cat <<EOF
Usage: bash scripts/go_live_wizard.sh [--help]

Walks you through taking River Monitor public at $PUBLIC_URL:
  1  preflight: River checkout on an up-to-date main, docker/gh/git ready
  2  tunnel repo: private GitHub remote + push (skipped if origin exists)
  3  docker network public-edge on the Docker host (skipped if present)
  4  Cloudflare: create the tunnel, save TUNNEL_TOKEN to the tunnel .env
  5  Cloudflare: add the river.ohr3023.org route (path regex) + check 404 catch-all
  6  TRUSTED_PROXY_COUNT=1 in River's .env
  7  rebuild and recreate River from main, wait for healthy
  8  BotFather token + public_base_url into River's Settings (never echoed)
  9  start the tunnel, wait for a registered connection
 10  public-edge smoke check against $PUBLIC_URL
 11  send /start to the bot

Safe to re-run: finished steps are detected and skipped, or offered as skips.
Env overrides: RIVER_DIR=$RIVER_DIR
               RIVER_PROJECT=$RIVER_PROJECT
               TUNNEL_DIR=$TUNNEL_DIR
               TUNNEL_REPO_NAME=$TUNNEL_REPO_NAME
EOF
}

# Compose wrappers pin the project name and file so a run from anywhere
# targets the live containers (my_river_level-app-1), never a second copy.
river_compose()  { docker compose -p "$RIVER_PROJECT" -f "$RIVER_DIR/docker-compose.yml" "$@"; }
tunnel_compose() { docker compose -p "$TUNNEL_PROJECT" -f "$TUNNEL_DIR/docker-compose.yml" "$@"; }

# river_setting_get KEY prints a Settings value from the running app.
river_setting_get() {
  river_compose exec -T app python -c \
    'import sys; from db.models import get_setting; print(get_setting(sys.argv[1]) or "")' "$1"
}

# river_setting_put KEY writes stdin as KEY's value. The value travels over
# stdin only, so it never appears in argv, shell history or the terminal.
river_setting_put() {
  river_compose exec -T app python -c \
    'import sys; from db.models import set_setting; set_setting(sys.argv[1], sys.stdin.read().strip())' "$1"
}

# drop_env_key KEY removes KEY's line from ENV_FILE (used to discard a
# placeholder so ask_secret doesn't offer it as "current").
drop_env_key() {
  local key="$1" tmp
  [[ -f "$ENV_FILE" ]] || return 0
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
}

# app_health prints the app container's health status, or "missing".
app_health() {
  local id
  id=$(river_compose ps -q app 2>/dev/null || true)
  [[ -n "$id" ]] || { printf 'missing'; return 0; }
  docker inspect -f '{{if .State.Health}}{{.State.Health.Status}}{{else}}{{.State.Status}}{{end}}' "$id" 2>/dev/null || printf 'missing'
}

run_wizard() {

if [[ "${1:-}" == "-h" || "${1:-}" == "--help" ]]; then usage; return 0; fi

TOTAL_STAGES=11

banner "River Monitor go-live"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Preflight checks"
command -v git >/dev/null 2>&1 || die "git is not on PATH."
command -v docker >/dev/null 2>&1 || die "docker CLI is not on PATH."
command -v gh >/dev/null 2>&1 || die "gh (GitHub CLI) is not on PATH."
gh auth status >/dev/null 2>&1 || die "gh is not logged in: run 'gh auth login', then re-run."
ctx=$(docker context show 2>/dev/null || true)
case "$ctx" in
  default|desktop-linux|"") die "docker context is '$ctx'; switch to the remote Docker host's context first." ;;
esac
docker info >/dev/null 2>&1 || die "docker context '$ctx' does not answer (docker info failed)."
step "docker context: $ctx (reachable)"

[[ -f "$RIVER_DIR/docker-compose.yml" ]] || die "No docker-compose.yml in RIVER_DIR=$RIVER_DIR."
[[ -f "$RIVER_DIR/.env" ]] || die "River has no .env yet; see docs/howto/this-deployment.md (Environment file)."
if [[ "$(git -C "$RIVER_DIR" rev-parse --git-dir)" != "$(git -C "$RIVER_DIR" rev-parse --git-common-dir)" ]]; then
  die "$RIVER_DIR is a git worktree. Run the wizard from the main River checkout."
fi
branch=$(git -C "$RIVER_DIR" rev-parse --abbrev-ref HEAD)
[[ "$branch" == "main" ]] || die "River checkout is on '$branch', not main. Merge PR #9, then: git checkout main; git pull."
[[ -z "$(git -C "$RIVER_DIR" status --porcelain --untracked-files=no)" ]] \
  || die "River checkout has uncommitted changes to tracked files; commit or discard them first."
say "Fetching origin/main…"
git -C "$RIVER_DIR" fetch --quiet origin main || die "git fetch origin main failed."
local_sha=$(git -C "$RIVER_DIR" rev-parse HEAD)
remote_sha=$(git -C "$RIVER_DIR" rev-parse origin/main)
[[ "$local_sha" == "$remote_sha" ]] \
  || die "Local main ($local_sha) differs from origin/main ($remote_sha). Run: git pull --ff-only"
grep -q "public-edge" "$RIVER_DIR/docker-compose.yml" \
  || die "main does not include the public-edge change yet. Merge PR #9, then git pull and re-run."
step "River: main @ ${local_sha:0:7}, up to date, includes public-edge"

if [[ ! -f "$TUNNEL_DIR/docker-compose.yml" ]]; then
  warn "No tunnel project at $TUNNEL_DIR."
  ask TUNNEL_DIR "Path to the cloudflare-tunnel checkout:"
  [[ -f "$TUNNEL_DIR/docker-compose.yml" ]] || die "No docker-compose.yml in $TUNNEL_DIR."
fi
TUNNEL_DIR=$(cd "$TUNNEL_DIR" && pwd)
step "tunnel project: $TUNNEL_DIR"
command -v uv >/dev/null 2>&1 || warn "uv not on PATH; the smoke check will fall back to python."
pause "Preflight passed. Continue?"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Tunnel repo: private GitHub remote"
if origin=$(git -C "$TUNNEL_DIR" remote get-url origin 2>/dev/null); then
  note "origin already set ($origin): skipping."
else
  if git -C "$TUNNEL_DIR" ls-files --error-unmatch .env >/dev/null 2>&1; then
    die "The tunnel repo TRACKS .env. Untrack it (git rm --cached .env) and commit before pushing."
  fi
  git -C "$TUNNEL_DIR" check-ignore -q .env || die "The tunnel repo does not ignore .env; fix .gitignore first."
  [[ -z "$(git -C "$TUNNEL_DIR" status --porcelain)" ]] || die "The tunnel repo has uncommitted changes; commit them first."
  owner=$(gh api user --jq .login)
  say "This creates the PRIVATE repo $owner/$TUNNEL_REPO_NAME and pushes the tunnel project."
  note ".env is gitignored and stays local."
  if confirm "Create $owner/$TUNNEL_REPO_NAME (private) and push?"; then
    if gh repo view "$owner/$TUNNEL_REPO_NAME" >/dev/null 2>&1; then
      note "$owner/$TUNNEL_REPO_NAME already exists on GitHub; adding it as origin."
      git -C "$TUNNEL_DIR" remote add origin "https://github.com/$owner/$TUNNEL_REPO_NAME.git"
      git -C "$TUNNEL_DIR" push -u origin HEAD
    else
      gh repo create "$TUNNEL_REPO_NAME" --private --source "$TUNNEL_DIR" --remote origin --push
    fi
    vis=$(gh repo view "$owner/$TUNNEL_REPO_NAME" --json visibility --jq .visibility 2>/dev/null || echo unknown)
    [[ "$vis" == "PRIVATE" ]] || warn "GitHub reports visibility '$vis' for $owner/$TUNNEL_REPO_NAME; make it private."
    printf '  %s✓ pushed%s %s/%s\n' "$GREEN" "$RESET" "$owner" "$TUNNEL_REPO_NAME"
  else
    SKIPPED+=("tunnel repo GitHub remote (re-run the wizard to create it)")
  fi
fi
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Docker network public-edge"
say "River's compose now joins the external public-edge network, so it must exist"
say "before River is redeployed."
if docker network inspect public-edge >/dev/null 2>&1; then
  note "public-edge already exists on the Docker host: skipping."
else
  if confirm "Create network public-edge on the Docker host ($ctx)?"; then
    docker network create public-edge >/dev/null
    printf '  %s✓ created%s network public-edge\n' "$GREEN" "$RESET"
  else
    die "public-edge is required before River can be redeployed. Re-run when ready."
  fi
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: create the tunnel and save its token"
ENV_FILE="$TUNNEL_DIR/.env"
[[ -f "$ENV_FILE" ]] || [[ ! -f "$TUNNEL_DIR/.env.example" ]] || (umask 077 && cp "$TUNNEL_DIR/.env.example" "$ENV_FILE")
current=$(_existing TUNNEL_TOKEN || true)
need_token=1
if [[ "$current" == "$PLACEHOLDER_TOKEN" ]]; then
  drop_env_key TUNNEL_TOKEN
  note "Discarded the placeholder TUNNEL_TOKEN; a real one is needed."
elif [[ -n "$current" ]]; then
  note "A tunnel token is already saved in $ENV_FILE."
  confirm "Replace it with a new one?" || need_token=0
fi
if (( need_token )); then
  open_url "$CF_DASHBOARD"
  step "Pick the account for ohr3023.org → Networks → Tunnels → Create a tunnel."
  step "Choose Cloudflared, name it (e.g. river-edge), and save."
  step "On 'Install and run a connector', choose Docker and copy the command shown"
  step "(docker run … --token eyJ…). Paste the whole command or just the token."
  note "If the tunnel already exists: open it → Configure → copy the same command."
  while :; do
    ask_secret TUNNEL_TOKEN "Paste the tunnel token (hidden):" || die "No token entered."
    TUNNEL_TOKEN="${TUNNEL_TOKEN%"${TUNNEL_TOKEN##*[![:space:]]}"}"  # trim trailing space
    TUNNEL_TOKEN="${TUNNEL_TOKEN##* }"                                 # keep last word
    if [[ -z "$TUNNEL_TOKEN" || "$TUNNEL_TOKEN" == "$PLACEHOLDER_TOKEN" || "$TUNNEL_TOKEN" == --* ]]; then
      warn "That isn't a tunnel token; try again."
      continue
    fi
    break
  done
  write_env TUNNEL_TOKEN "$TUNNEL_TOKEN"
  unset TUNNEL_TOKEN
fi
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: route river.ohr3023.org (public pages only)"
if confirm "Is the river.ohr3023.org route already configured exactly as the tunnel README records? (y skips)"; then
  note "Skipping the route setup."
else
  open_url "$CF_DASHBOARD"
  step "Networks → Tunnels → your tunnel → Edit → Public Hostname (newer dashboards:"
  step "'Published application routes') → Add a public hostname."
  step "Subdomain: river     Domain: ohr3023.org"
  step "Path (type it exactly, no surrounding quotes):"
  printf '\n      %s%s%s\n\n' "$BOLD" "$PATH_REGEX" "$RESET"
  step "Service: Type HTTP, URL river-app:5743   → Save."
  step "Do NOT add a catch-all yourself: check the tunnel's ingress list ends with"
  step "the automatic http_status:404 rule."
  if ! confirm "Route saved and the http_status:404 catch-all is last?"; then
    SKIPPED+=("Cloudflare route for river.ohr3023.org (see the tunnel README)")
    warn "Recorded as still to do; the smoke check will fail until it's done."
  fi
fi
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "River: trust one proxy hop"
ENV_FILE="$RIVER_DIR/.env"
say "Behind cloudflared (public) or Traefik (tailnet) there is exactly one proxy hop."
if [[ "$(_existing TRUSTED_PROXY_COUNT || true)" == "1" ]]; then
  note "TRUSTED_PROXY_COUNT=1 already set in $ENV_FILE: skipping."
else
  write_env TRUSTED_PROXY_COUNT 1
fi
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "River: rebuild and recreate from main"
say "Health now: $(app_health)"
if confirm "Rebuild and recreate River's app (docker compose up -d --build)?"; then
  river_compose up -d --build
else
  note "Not rebuilding; the next stages need the app running with the current build."
fi
say "Waiting for the app to report healthy (up to 3 minutes)…"
health=""
for _ in $(seq 1 36); do
  health=$(app_health)
  [[ "$health" == "healthy" ]] && break
  sleep 5
done
[[ "$health" == "healthy" ]] || die "App is '$health', not healthy. See docs/howto/diagnose.md, then re-run."
printf '  %s✓ app healthy%s\n' "$GREEN" "$RESET"
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Telegram bot token and public URL into Settings"
need_bot=1
if [[ -n "$(river_setting_get telegram_bot_token | tr -d '\r')" ]]; then
  note "A Telegram bot token is already set in Settings."
  confirm "Replace it?" || need_bot=0
fi
if (( need_bot )); then
  open_url "https://t.me/BotFather"
  step "In Telegram, message @BotFather and send /newbot."
  step "Give a display name, then a username ending in 'bot'."
  step "Copy the token it replies with (looks like 123456789:AAE…)."
  note "Existing bot? Send /mybots → pick it → API Token."
  while :; do
    ask_secret TG_BOT_TOKEN "Paste the bot token (hidden):" || die "No token entered."
    TG_BOT_TOKEN="${TG_BOT_TOKEN//[[:space:]]/}"
    [[ "$TG_BOT_TOKEN" =~ ^[0-9]+:[A-Za-z0-9_-]+$ ]] && break
    warn "That doesn't look like a bot token (digits:letters); try again."
  done
  printf '%s' "$TG_BOT_TOKEN" | river_setting_put telegram_bot_token
  unset TG_BOT_TOKEN
  printf '  %s✓ wrote%s telegram_bot_token → Settings\n' "$GREEN" "$RESET"
fi
if [[ "$(river_setting_get public_base_url | tr -d '\r')" == "$PUBLIC_URL" ]]; then
  note "public_base_url already $PUBLIC_URL."
else
  printf '%s' "$PUBLIC_URL" | river_setting_put public_base_url
  printf '  %s✓ wrote%s public_base_url=%s → Settings\n' "$GREEN" "$RESET" "$PUBLIC_URL"
fi
say "Waiting for the bot to connect (it records its username; up to 90 s)…"
for _ in $(seq 1 18); do
  BOT_USERNAME=$(river_setting_get telegram_bot_username | tr -d '\r' || true)
  [[ -n "$BOT_USERNAME" ]] && break
  sleep 5
done
if [[ -n "$BOT_USERNAME" ]]; then
  printf '  %s✓ bot connected%s as @%s\n' "$GREEN" "$RESET" "$BOT_USERNAME"
else
  warn "No bot username yet: the token may be wrong (see docs/howto/diagnose.md)."
  SKIPPED+=("confirm the Telegram bot connected (telegram_bot_username is empty)")
fi
pause

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Start the Cloudflare tunnel"
if confirm "Start (or update) the tunnel project (docker compose up -d)?"; then
  tunnel_compose up -d
  say "Waiting for a registered tunnel connection (up to 60 s)…"
  registered=0
  for _ in $(seq 1 12); do
    logs=$(tunnel_compose logs --tail 100 cloudflared 2>&1 || true)
    if [[ "$logs" == *"Registered tunnel connection"* ]]; then registered=1; break; fi
    sleep 5
  done
  if (( registered )); then
    printf '  %s✓ tunnel connected%s\n' "$GREEN" "$RESET"
  else
    warn "No 'Registered tunnel connection' yet. Check: docker compose logs cloudflared (in $TUNNEL_DIR)."
  fi
else
  SKIPPED+=("start the tunnel: docker compose up -d in $TUNNEL_DIR")
fi
pause

# ── 10 ───────────────────────────────────────────────────────────────────
stage "Smoke-check the public edge"
found=$(river_compose exec -T app python -c \
  "from db.models import get_db; c=get_db(); cur=c.cursor(); cur.execute(\"select public_token from user_pages where status='active' order by id desc limit 1\"); r=cur.fetchone(); print(r['public_token'] if r else '')" \
  2>/dev/null | tr -d '\r' || true)
if [[ -n "$found" ]]; then
  say "Latest active page's public token: $found"
  note "Enter uses it; type - to skip the /view check; or paste another token."
else
  note "No active page found. Paste a public token, or press Enter to skip the /view check."
fi
read -r -p "  View token: " view_token || true
[[ -z "$view_token" ]] && view_token="$found"
[[ "$view_token" == "-" ]] && view_token=""
smoke_args=(--base-url "$PUBLIC_URL")
[[ -n "$view_token" ]] && smoke_args+=(--view-token "$view_token")
if command -v uv >/dev/null 2>&1; then
  runner=(uv run --no-project python)
elif command -v python >/dev/null 2>&1; then
  runner=(python)
else
  runner=(python3)
fi
printf '\n'
if "${runner[@]}" "$RIVER_DIR/scripts/smoke_public_edge.py" "${smoke_args[@]}"; then
  SMOKE_RESULT="PASS"
  printf '\n  %s✓ smoke check passed%s\n' "$GREEN" "$RESET"
else
  SMOKE_RESULT="FAIL"
  warn "Smoke check FAILED. See docs/howto/this-deployment.md (Public edge) and re-run."
  SKIPPED+=("make the smoke check pass: python scripts/smoke_public_edge.py")
fi
pause

# ── 11 ───────────────────────────────────────────────────────────────────
stage "Say hello to the bot"
if [[ -n "$BOT_USERNAME" ]]; then
  open_url "https://t.me/$BOT_USERNAME"
else
  step "Open your bot in Telegram."
fi
step "Send /start."
step "Expect a welcome reply with a map link starting $PUBLIC_URL/pin/…"
step "Open it, drop a pin, save; expect a '✓ You're set up for …' message."
if ! confirm "Did the bot reply with a $PUBLIC_URL map link?"; then
  SKIPPED+=("bot /start reply (see docs/howto/diagnose.md#telegram-bot-is-silent)")
fi

finish
note "smoke check: $SMOKE_RESULT"
printf '\n'
[[ "$SMOKE_RESULT" == "PASS" ]]
}

run_wizard "$@"; exit
